import{bV as e,aL as l,u as t,G as i}from"./chunks/framework.DvBUyM1S.js";const p=JSON.parse('{"title":"关于 - 我","description":"","frontmatter":{"title":"关于 - 我","date":"2022-04-16T17:52:59.000Z","permalink":"/about/me/","categories":[null],"tags":[null]},"headers":[],"relativePath":"about/me.md","filePath":"08.关于/01.关于-我.md","lastUpdated":1787815286000}'),o={name:"about/me.md"};function r(h,a,n,d,c,s){return l(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="关于-我" tabindex="-1">关于 - 我 <a class="header-anchor" href="#关于-我" aria-label="Permalink to &quot;关于 - 我&quot;">​</a></h1><nav class="table-of-contents"><ul><li><a href="#读者的问题与回答">读者的问题与回答</a><ul><li><a href="#qa-做这个网站的初衷是什么">QA - 做这个网站的初衷是什么</a></li><li><a href="#qa-是否可以有机会合作">QA - 是否可以有机会合作</a></li><li><a href="#qa-是否可以提供技术支持">QA - 是否可以提供技术支持</a></li><li><a href="#qa-是否考虑变现">QA - 是否考虑变现</a></li><li><a href="#qa-网站运营">QA - 网站运营</a></li><li><a href="#我的三观">我的三观</a></li><li><a href="#联系我">联系我</a></li><li><a href="#更多">更多</a></li></ul></li></ul></nav><h2 id="读者的问题与回答" tabindex="-1">读者的问题与回答 <a class="header-anchor" href="#读者的问题与回答" aria-label="Permalink to &quot;读者的问题与回答&quot;">​</a></h2><h3 id="qa-做这个网站的初衷是什么" tabindex="-1">QA - 做这个网站的初衷是什么 <a class="header-anchor" href="#qa-做这个网站的初衷是什么" aria-label="Permalink to &quot;QA - 做这个网站的初衷是什么&quot;">​</a></h3><p>兴趣使然，将学到的东西都记录下来。</p><ul><li>知识碎片化，对知识没有形成体系。</li><li>忙于业务代码，忙到忘记思考。</li><li>在焦虑中心态焦灼学习中艰难前行。</li></ul><h3 id="qa-是否可以有机会合作" tabindex="-1">QA - 是否可以有机会合作 <a class="header-anchor" href="#qa-是否可以有机会合作" aria-label="Permalink to &quot;QA - 是否可以有机会合作&quot;">​</a></h3><p>当然可以，你可以在本页找到我。</p><h3 id="qa-是否可以提供技术支持" tabindex="-1">QA - 是否可以提供技术支持 <a class="header-anchor" href="#qa-是否可以提供技术支持" aria-label="Permalink to &quot;QA - 是否可以提供技术支持&quot;">​</a></h3><p>当然可以，如果我刚好不忙的话，很愿意互相交流一下。</p><h3 id="qa-是否考虑变现" tabindex="-1">QA - 是否考虑变现 <a class="header-anchor" href="#qa-是否考虑变现" aria-label="Permalink to &quot;QA - 是否考虑变现&quot;">​</a></h3><p>暂不会考虑将网站及内容作为商业用途，后期也尽可能不加入广告。</p><h3 id="qa-网站运营" tabindex="-1">QA - 网站运营 <a class="header-anchor" href="#qa-网站运营" aria-label="Permalink to &quot;QA - 网站运营&quot;">​</a></h3><p>免费服务器储存<code>GitHub Pages</code>，缓存<code>Cloudflare</code>，图片使用<code>OSS</code>确保资源不丢失，域名续费10年以维持网站长期存在。</p><h3 id="我的三观" tabindex="-1">我的三观 <a class="header-anchor" href="#我的三观" aria-label="Permalink to &quot;我的三观&quot;">​</a></h3><p>我是性格内向，喜欢独处，懒惰的人，也是一个空闲之余喜欢编程的人，喜欢学习新技术，喜欢分享知识，喜欢分享生活。</p><p><img src="https://feyoudao.oss-cn-hongkong.aliyuncs.com/mweb/me-life.png" alt="image" loading="lazy"></p><h3 id="联系我" tabindex="-1">联系我 <a class="header-anchor" href="#联系我" aria-label="Permalink to &quot;联系我&quot;">​</a></h3><br><img src="http://r2-site.feyoudao.cn/public_logo.jpeg" width="700" alt="wechat"><h3 id="更多" tabindex="-1">更多 <a class="header-anchor" href="#更多" aria-label="Permalink to &quot;更多&quot;">​</a></h3><blockquote><p>加入学习交流群。</p></blockquote><p>一起学习和技术交流，请添加我微信，我会直接将你拉进前端有道交流群。合作意向，请表明来意。</p><img src="http://r2-site.feyoudao.cn/wechat.jpeg" width="300" height="300" alt="wechat">',24)])])}const q=e(o,[["render",r]]);export{p as __pageData,q as default};
